/**
 * Validator for the 30-day experiment operating board.
 *
 * The board is two files that must agree: a Markdown table humans read
 * (docs/marketing/experiments-board.md) and the JSON this module validates
 * (docs/marketing/experiments-board.json). The JSON is authoritative for
 * machines; the Markdown is authoritative for nobody and must be regenerated by
 * hand from it.
 *
 * WHAT THIS REFUSES TO ACCEPT, and why each rule exists:
 *
 *  - duplicate experiment_id .......... two rows reporting into one identity
 *  - bad or inverted dates ............ a window nobody can check a result against
 *  - unknown status ................... status drives every downstream gate
 *  - negative spend cap ............... a cap that is not a cap
 *  - malformed or PII-like UTM ........ see ./utm-contract.ts; a partner link is
 *                                       printed on paper and cannot be recalled
 *  - colliding UTM tuples ............. two experiments GA4 cannot tell apart
 *  - live without posting approval .... something public happened unapproved
 *  - paid without spend approval/cap .. money moved unapproved
 *  - missing 24h/48h/7d/30d checkpoints  a board with no checkpoints is a wish list
 *  - missing decision / next_action ... a row nobody has to close out
 *
 * Pure: no filesystem, no network. The caller supplies parsed JSON.
 */

import {
  PAID_UTM_MEDIUMS,
  utmTupleKey,
  validateUtmTuple,
  type GovernedUtmTuple,
} from './utm-contract.ts';

export const EXPERIMENT_BOARD_SCHEMA_VERSION = '1.0.0';

export const EXPERIMENT_STATUSES = ['proposed', 'approved', 'live', 'paused', 'completed', 'invalid'] as const;
export type ExperimentStatus = (typeof EXPERIMENT_STATUSES)[number];

/** Statuses that mean something is, or has been, publicly visible. */
export const PUBLIC_STATUSES = new Set<ExperimentStatus>(['live', 'paused', 'completed']);

export const REQUIRED_CHECKPOINTS = ['24h', '48h', '7d', '30d'] as const;
export type CheckpointAt = (typeof REQUIRED_CHECKPOINTS)[number];

/**
 * Evidence quality is a first-class field so an unmeasured number can never be
 * mistaken for a measured one. 'measured' requires a named source.
 */
export const EVIDENCE_QUALITIES = ['measured', 'estimate', 'unverified'] as const;
export type EvidenceQuality = (typeof EVIDENCE_QUALITIES)[number];

export const APPROVAL_KINDS = ['public_posting', 'account_connection', 'paid_spend'] as const;
export type ApprovalKind = (typeof APPROVAL_KINDS)[number];

export interface ApprovalRecord {
  granted: boolean;
  approver: string | null;
  date: string | null;
  evidence: string | null;
}

export interface MetricRecord {
  metric: string;
  value: number | null;
  quality: EvidenceQuality;
  note: string;
}

export interface CheckpointRecord {
  at: CheckpointAt;
  due_date: string;
  result: string | null;
  quality: EvidenceQuality;
}

export interface ExperimentRow {
  experiment_id: string;
  business: string;
  hypothesis: string;
  audience: string;
  offer: string;
  channel: string;
  funnel: string;
  creative_or_link: string;
  landing_page: string;
  utm: GovernedUtmTuple;
  start_date: string;
  end_date: string;
  owner: string;
  status: ExperimentStatus;
  spend_cap_usd: number;
  capacity_constraint: string;
  unit_economics: string;
  primary_conversion: string;
  guardrails: string[];
  baseline: MetricRecord;
  target: MetricRecord;
  actual: MetricRecord;
  evidence_quality: EvidenceQuality;
  major_variable: string;
  checkpoints: CheckpointRecord[];
  keep_kill_iterate: string;
  decision: string;
  next_action: string;
  approvals: Record<ApprovalKind, ApprovalRecord>;
}

export interface ExperimentBoard {
  schema_version: string;
  generated_by: string;
  experiments: ExperimentRow[];
}

export interface BoardValidationResult {
  ok: boolean;
  errors: string[];
}

const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function isIsoDate(value: unknown): value is string {
  if (typeof value !== 'string' || !ISO_DATE_RE.test(value)) return false;
  const parsed = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}

function requireNonEmptyString(value: unknown, field: string, errors: string[]): void {
  if (typeof value !== 'string' || value.trim() === '') errors.push(`${field} must be a non-empty string`);
}

function validateMetric(value: unknown, field: string, errors: string[]): void {
  if (value === null || typeof value !== 'object') { errors.push(`${field} must be an object`); return; }
  const metric = value as Record<string, unknown>;
  requireNonEmptyString(metric.metric, `${field}.metric`, errors);
  requireNonEmptyString(metric.note, `${field}.note`, errors);
  if (metric.value !== null && typeof metric.value !== 'number') {
    errors.push(`${field}.value must be a number or null`);
  }
  if (!(EVIDENCE_QUALITIES as readonly unknown[]).includes(metric.quality)) {
    errors.push(`${field}.quality must be one of ${EVIDENCE_QUALITIES.join(', ')}`);
  }
  // The rule that keeps invented results out: a number you have not measured
  // must not claim to be measured, and a measured claim must carry a number.
  if (metric.quality === 'measured' && metric.value === null) {
    errors.push(`${field} claims quality 'measured' with no value`);
  }
  if (metric.quality !== 'measured' && metric.value !== null && !/estimate|unverified|assum|target|plan/i.test(String(metric.note))) {
    errors.push(`${field} carries a non-measured value whose note does not mark it as an estimate or unverified`);
  }
}

function validateApproval(value: unknown, field: string, errors: string[]): ApprovalRecord | null {
  if (value === null || typeof value !== 'object') { errors.push(`${field} must be an object`); return null; }
  const approval = value as Record<string, unknown>;
  if (typeof approval.granted !== 'boolean') errors.push(`${field}.granted must be a boolean`);
  for (const key of ['approver', 'date', 'evidence'] as const) {
    if (approval[key] !== null && typeof approval[key] !== 'string') {
      errors.push(`${field}.${key} must be a string or null`);
    }
  }
  if (approval.granted === true) {
    // A granted approval with nobody's name on it is not an approval.
    if (!approval.approver) errors.push(`${field} is granted with no approver`);
    if (!isIsoDate(approval.date)) errors.push(`${field} is granted with no valid ISO date`);
    if (!approval.evidence) errors.push(`${field} is granted with no evidence reference`);
  }
  return approval as unknown as ApprovalRecord;
}

function validateCheckpoints(value: unknown, field: string, errors: string[]): void {
  if (!Array.isArray(value)) { errors.push(`${field} must be an array`); return; }
  const seen = value.map((entry) => (entry && typeof entry === 'object' ? (entry as Record<string, unknown>).at : undefined));
  for (const required of REQUIRED_CHECKPOINTS) {
    if (!seen.includes(required)) errors.push(`${field} is missing the ${required} checkpoint`);
  }
  for (const entry of seen) {
    if (entry !== undefined && !(REQUIRED_CHECKPOINTS as readonly unknown[]).includes(entry)) {
      errors.push(`${field} contains unknown checkpoint '${String(entry)}'`);
    }
  }
  if (new Set(seen).size !== seen.length) errors.push(`${field} contains duplicate checkpoints`);

  value.forEach((entry, index) => {
    const label = `${field}[${index}]`;
    if (entry === null || typeof entry !== 'object') { errors.push(`${label} must be an object`); return; }
    const checkpoint = entry as Record<string, unknown>;
    if (!isIsoDate(checkpoint.due_date)) errors.push(`${label}.due_date must be an ISO date`);
    if (checkpoint.result !== null && typeof checkpoint.result !== 'string') {
      errors.push(`${label}.result must be a string or null`);
    }
    if (!(EVIDENCE_QUALITIES as readonly unknown[]).includes(checkpoint.quality)) {
      errors.push(`${label}.quality must be one of ${EVIDENCE_QUALITIES.join(', ')}`);
    }
    if (checkpoint.quality === 'measured' && !checkpoint.result) {
      errors.push(`${label} claims quality 'measured' with no result`);
    }
  });
}

/** Validate one row. Returns the governed tuple when it parsed, else null. */
function validateRow(raw: unknown, index: number, errors: string[]): GovernedUtmTuple | null {
  const label = `experiments[${index}]`;
  if (raw === null || typeof raw !== 'object') { errors.push(`${label} must be an object`); return null; }
  const row = raw as Record<string, unknown>;

  for (const field of [
    'experiment_id', 'business', 'hypothesis', 'audience', 'offer', 'channel', 'funnel',
    'creative_or_link', 'landing_page', 'owner', 'capacity_constraint', 'unit_economics',
    'primary_conversion', 'major_variable', 'keep_kill_iterate', 'decision', 'next_action',
  ]) {
    requireNonEmptyString(row[field], `${label}.${field}`, errors);
  }

  if (!(EXPERIMENT_STATUSES as readonly unknown[]).includes(row.status)) {
    errors.push(`${label}.status must be one of ${EXPERIMENT_STATUSES.join(', ')}`);
  }
  if (!(EVIDENCE_QUALITIES as readonly unknown[]).includes(row.evidence_quality)) {
    errors.push(`${label}.evidence_quality must be one of ${EVIDENCE_QUALITIES.join(', ')}`);
  }
  if (!Array.isArray(row.guardrails) || row.guardrails.length === 0
    || row.guardrails.some((g) => typeof g !== 'string' || g.trim() === '')) {
    errors.push(`${label}.guardrails must be a non-empty array of strings`);
  }

  if (!isIsoDate(row.start_date)) errors.push(`${label}.start_date must be an ISO date`);
  if (!isIsoDate(row.end_date)) errors.push(`${label}.end_date must be an ISO date`);
  if (isIsoDate(row.start_date) && isIsoDate(row.end_date) && row.end_date < row.start_date) {
    errors.push(`${label}.end_date is before start_date`);
  }

  if (typeof row.spend_cap_usd !== 'number' || Number.isNaN(row.spend_cap_usd)) {
    errors.push(`${label}.spend_cap_usd must be a number`);
  } else if (row.spend_cap_usd < 0) {
    errors.push(`${label}.spend_cap_usd must not be negative`);
  }

  validateMetric(row.baseline, `${label}.baseline`, errors);
  validateMetric(row.target, `${label}.target`, errors);
  validateMetric(row.actual, `${label}.actual`, errors);
  validateCheckpoints(row.checkpoints, `${label}.checkpoints`, errors);

  const approvals = (row.approvals ?? null) as Record<string, unknown> | null;
  if (approvals === null || typeof approvals !== 'object') {
    errors.push(`${label}.approvals must be an object`);
  } else {
    for (const kind of APPROVAL_KINDS) {
      validateApproval(approvals[kind], `${label}.approvals.${kind}`, errors);
    }
  }

  const utmResult = validateUtmTuple(row.utm);
  if (!utmResult.ok) {
    for (const error of utmResult.errors ?? []) errors.push(`${label}.${error}`);
  }

  const status = row.status as ExperimentStatus;
  const postingGranted = Boolean((approvals?.public_posting as ApprovalRecord | undefined)?.granted);
  const spendGranted = Boolean((approvals?.paid_spend as ApprovalRecord | undefined)?.granted);

  if (PUBLIC_STATUSES.has(status) && !postingGranted) {
    errors.push(`${label} has status '${status}' without a granted public_posting approval`);
  }

  const connectionGranted = Boolean((approvals?.account_connection as ApprovalRecord | undefined)?.granted);
  const medium = utmResult.ok ? utmResult.tuple.utm_medium : null;
  const isPaid = medium !== null && PAID_UTM_MEDIUMS.has(medium);

  if (isPaid) {
    // A paid row must declare its cap the moment it is written down, even while
    // proposed — an uncapped proposal is what gets waved through later.
    if (typeof row.spend_cap_usd === 'number' && row.spend_cap_usd <= 0) {
      errors.push(`${label} uses paid medium '${medium}' with no positive spend cap`);
    }
    // The three approvals are separate on purpose: permission to post publicly,
    // permission to connect an ad account, and permission to spend are three
    // different decisions by (potentially) three different people.
    if (PUBLIC_STATUSES.has(status)) {
      if (!spendGranted) errors.push(`${label} uses paid medium '${medium}' at status '${status}' without a granted paid_spend approval`);
      if (!connectionGranted) errors.push(`${label} uses paid medium '${medium}' at status '${status}' without a granted account_connection approval`);
    }
  } else if (typeof row.spend_cap_usd === 'number' && row.spend_cap_usd > 0) {
    // Ad spend only. Production costs (printing flyers) are tracked in
    // unit_economics, not here, so a non-paid row carrying a cap is a
    // mis-classified row.
    errors.push(`${label} declares a spend cap on non-paid medium '${medium ?? 'unknown'}'`);
  }

  return utmResult.ok ? utmResult.tuple : null;
}

/** Validate the whole board. Returns every error, not just the first. */
export function validateExperimentBoard(raw: unknown): BoardValidationResult {
  const errors: string[] = [];

  if (raw === null || typeof raw !== 'object') {
    return { ok: false, errors: ['board must be an object'] };
  }
  const board = raw as Record<string, unknown>;
  if (board.schema_version !== EXPERIMENT_BOARD_SCHEMA_VERSION) {
    errors.push(`schema_version must be '${EXPERIMENT_BOARD_SCHEMA_VERSION}'`);
  }
  requireNonEmptyString(board.generated_by, 'generated_by', errors);
  if (!Array.isArray(board.experiments)) {
    errors.push('experiments must be an array');
    return { ok: false, errors };
  }

  const seenIds = new Set<string>();
  const seenTuples = new Map<string, string>();

  board.experiments.forEach((row, index) => {
    const tuple = validateRow(row, index, errors);
    const id = (row as Record<string, unknown>)?.experiment_id;
    if (typeof id === 'string' && id.trim() !== '') {
      if (seenIds.has(id)) errors.push(`duplicate experiment_id '${id}'`);
      seenIds.add(id);
    }
    if (tuple) {
      const key = utmTupleKey(tuple);
      const owner = seenTuples.get(key);
      if (owner !== undefined) {
        errors.push(`experiments[${index}] shares its governed UTM tuple with '${owner}' (${key})`);
      } else if (typeof id === 'string') {
        seenTuples.set(key, id);
      }
    }
  });

  return { ok: errors.length === 0, errors };
}
